    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = DateTime.UtcNow });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// Cosmos DB context demonstrating EF Core 9 breaking change fixes
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "CatalogDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // BREAKING CHANGE FIX #1: EF Core 9 renamed the Cosmos discriminator
        // property from "Discriminator" to "$type". Existing documents still use
        // "Discriminator", so we must explicitly configure the old property name
        // to avoid query/deserialization failures.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        modelBuilder.Entity<Product>().ToContainer("Products");
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

// BREAKING CHANGE FIX #2: EF Core 9 Cosmos provider removed synchronous I/O
// support. All queries must use async methods (ToListAsync, FirstOrDefaultAsync,
// etc.) instead of ToList(), First(), etc.
class CosmosQueryService
{
    private readonly CosmosDbContext _db;
    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // Before (EF Core 8 - sync, now throws InvalidOperationException in EF9):
    //   var products = _db.Products.ToList();

    // After (EF Core 9 - must be async):
    public async Task<List<Product>> GetProductsAsync()
    {
        return await _db.Products.ToListAsync();
    }
}

