using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // BREAKING CHANGE FIX #3: EF Core 9 throws if Migrate() is called inside a
    // user-managed transaction. Migrate() now manages its own transaction(s).
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            db.Database.Migrate();
        });
    }
}

